package com.cryptostrategy.platform.evaluation.api.model;
import com.cryptostrategy.platform.backtesting.api.model.*;import com.cryptostrategy.platform.experiment.api.ExperimentId;import java.math.*;import java.time.Instant;import java.util.Objects;
public record EvaluationResult(EvaluationResultId evaluationResultId,ExperimentId experimentId,BacktestResultId backtestResultId,MetricVersion metricVersion,RankingVersion rankingVersion,BigDecimal totalReturn,BigDecimal winRate,BigDecimal maximumDrawdown,int numberOfTrades,BigDecimal overallScore,boolean leaderboardEligible,String fingerprint,Instant evaluatedAt){public EvaluationResult{Objects.requireNonNull(evaluationResultId);Objects.requireNonNull(experimentId);Objects.requireNonNull(backtestResultId);Objects.requireNonNull(metricVersion);Objects.requireNonNull(rankingVersion);totalReturn=metric(totalReturn);winRate=metric(winRate);maximumDrawdown=metric(maximumDrawdown);overallScore=metric(overallScore);Objects.requireNonNull(fingerprint);Objects.requireNonNull(evaluatedAt);if(numberOfTrades<0||overallScore.signum()<0||overallScore.compareTo(BigDecimal.ONE)>0)throw new IllegalArgumentException("Invalid evaluation");}private static BigDecimal metric(BigDecimal v){return Objects.requireNonNull(v).setScale(10,RoundingMode.HALF_EVEN);}}
